// app/dashboard/page.tsx (Server Component by default)
import { Chart } from './Chart';
import { RefreshButton } from './RefreshButton';
import { db } from '@/lib/db';

export default async function Page() {
  const metrics = await db.metrics.findMany();

  return (
    <main>
      <h1>Dashboard</h1>
      <Chart data={metrics} />
      <RefreshButton onRefresh={() => db.metrics.findMany()} />
    </main>
  );
}

// app/dashboard/Chart.tsx
import { useState } from 'react';

export function Chart({ data }: { data: Metric[] }) {
  const [zoom, setZoom] = useState(1);
  return <canvas data-zoom={zoom} onClick={() => setZoom((z) => z + 0.1)} />;
}

// app/dashboard/RefreshButton.tsx
'use client';

export function RefreshButton({ onRefresh }: { onRefresh: () => void }) {
  return <button onClick={() => onRefresh()}>Refresh</button>;
}
